static int br_fdb_insert_locals_per_vlan_port(struct net_bridge *br,
					      struct net_bridge_port *p,
					      struct netlink_ext_ack *extack)
{
	struct net_bridge_vlan_group *vg;
	struct net_bridge_vlan *v;
	struct net_device *dev;
	int err;

	if (p) {
		vg = nbp_vlan_group(p);
		dev = p->dev;
	} else {
		vg = br_vlan_group(br);
		dev = br->dev;
	}

	if (!vg)
